  var watch = function () {
    if (watch.on) return; watch.on = 1;
    TV.observe(visible, function (el, inView, x, io) { if (inView) { load(el); if (io) io.unobserve(el); } }, { rootMargin: '900px 0px 900px 0px', threshold: 0 });
  };
  var start = function () { watch(); silent.forEach(function (el, i) { setTimeout(function () { load(el); }, i * 40); }); };
  /* integration: while the hero film holds the first screen (html.hero-locked) nothing below it can be seen — the photos within
     900 px (company's 150 KB figure) wait for the page's load event (the film's first frame is in by then) or for the release,
     so they never compete with the film's first bytes. A free page (deep link, reduced motion, ?free=1) watches at once. */
  if (!document.documentElement.classList.contains('hero-locked')) watch(); else if (TV.on) TV.on('release', watch);
