    if (cfg.legalAddress) after('r2', sumRow('laddr', localized(cfg.legalAddress, cfg.legalAddressUz), { label: TV.t('summary.s.address') }));
    if (phoneShow && phoneHref) rowsEl.appendChild(sumRow('phone', phoneShow, { label: TV.t('contact.ch.phone'), href: 'tel:' + phoneHref, num: true }));
    if (email) rowsEl.appendChild(sumRow('email', email, { label: TV.t('contact.ch.email'), href: 'mailto:' + email }));
