      if (p.busy || m.releasing) return;                               /* a running move lands first ('state'); the release scroll settles */
      want = false; removeEventListener('scroll', onScroll);
      if (m.index === m.last) return;
      var off = hero.getBoundingClientRect().bottom <= 0;
